mapper.select:
select * from  Sec_Selection_Record_Dtl  ssrd
left join  Sec_Selection_Record ssr on ssr.Sr_Id=ssrd.Sr_Id
left join Sec_Expert se on ssrd.Ex_Id = se.Ex_Id

    ssr.State!=3
    
        and ssrd.Ex_Id=#{params.exId}
    
    
        and ssrd.Sr_Id=#{params.srId}
    
    
        and ssr.Sec_Id=#{params.secId}
    
    
        and ssrd.Srd_Attend = #{params.srdAttend}
    
    
    
        and ssr.Sec_Id not in
        
            #{item}

select mn.*, se.*, ssr.*, c1.C_Name as cName, c1.C_Abbreviation as cAbbName, c1.C_Name_History as cNameHistory, c2.C_Name as exApplicantCName, u1.U_Name as exApplicantName, pp.P_Name as pName, si.Sec_Name as secName, pp.P_Category as pCategory, secd.total_Deduction as totalDeduction, sec.Create_Time as ecCreateTime, sec.State as ecState, sec.id as ecId from Sec_Selection_Record_Dtl mn left join Sec_Selection_Record ssr on ssr.Sr_Id = mn.Sr_Id left join Sec_Expert_Check sec on sec.Sr_Id = ssr.Sr_Id left join Sec_Expert_Check_Detail secd on secd.ec_Id = sec.id and secd.Ex_Id = mn.Ex_Id left join Sec_Expert se on mn.Ex_Id = se.Ex_Id left join Sys_Company c1 on c1.C_Id=se.C_Id left join Sys_User u1 on u1.U_Id = se.Ex_Applicant_Id left join Sys_Company c2 on c2.C_Id = u1.C_Id left join Pre_project pp on pp.P_Id = ssr.P_Id left join Sec_Info si on si.Sec_Id = ssr.Sec_Id where ssr.State = 7 and mn.Srd_Attend = 1
and mn.Ex_Id=#{params.exId}
and mn.Sr_Id=#{params.srId}
and ssr.Sec_Id=#{params.secId}
